-- Sample loans share accounts, but grants, physical assets, agreements and money are independent.
CREATE TABLE sample_admin_grants (user_id TEXT PRIMARY KEY REFERENCES users(id), granted_by TEXT NOT NULL REFERENCES users(id), granted_at TEXT NOT NULL, revoked_at TEXT);
CREATE TABLE sample_models (model_key TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE);
INSERT INTO sample_models VALUES ('rm01-t234-32g','RM-01 32G T234 (275 TOPS)'),('rm01-t234-64g','RM-01 64G T234 (275 TOPS)'),('rm01-t4000-64g','RM-01 64G T4000 (1200 TFLOPS)'),('rm01-t5000-128g','RM-01 128G T5000 (2070 TFLOPS)');
CREATE TABLE sample_assets (id TEXT PRIMARY KEY, model_key TEXT NOT NULL REFERENCES sample_models(model_key), no TEXT NOT NULL, sn TEXT NOT NULL, no_key TEXT NOT NULL UNIQUE, sn_key TEXT NOT NULL UNIQUE, notes TEXT NOT NULL DEFAULT '', lifecycle TEXT NOT NULL DEFAULT 'active' CHECK(lifecycle IN ('active','lost','retired')), row_version INTEGER NOT NULL DEFAULT 1, created_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE sample_terms_versions (version TEXT PRIMARY KEY, notice_version TEXT NOT NULL, canonical_json TEXT NOT NULL, sha256 TEXT NOT NULL, created_at TEXT NOT NULL);
-- A fixed version must identify the exact accepted terms, including notices.
CREATE TRIGGER sample_terms_version_conflict BEFORE INSERT ON sample_terms_versions WHEN EXISTS(SELECT 1 FROM sample_terms_versions WHERE version=NEW.version AND sha256<>NEW.sha256) BEGIN SELECT RAISE(ABORT,'SAMPLE_TERMS_VERSION_CONFLICT'); END;
CREATE TABLE sample_requests (id TEXT PRIMARY KEY, public_no TEXT NOT NULL UNIQUE, status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected','completed','cancelled','loss_pending','loss_closed')), original_json TEXT NOT NULL, consent_json TEXT NOT NULL, draft_cipher TEXT, requested_days INTEGER NOT NULL CHECK(requested_days>0), model_key TEXT NOT NULL REFERENCES sample_models(model_key), search_text TEXT NOT NULL, display_name TEXT NOT NULL, submitted_at TEXT NOT NULL, row_version INTEGER NOT NULL DEFAULT 1, current_agreement_revision INTEGER NOT NULL DEFAULT 0, latest_ready_agreement_revision INTEGER NOT NULL DEFAULT 0, asset_id TEXT REFERENCES sample_assets(id), effective_start_at TEXT, effective_due_at TEXT, initial_term_days INTEGER, closed_at TEXT, financial_closed_at TEXT, hold_reason TEXT, purge_after_at TEXT, purge_started_at TEXT);
CREATE INDEX sample_requests_list ON sample_requests(status,submitted_at,id);
CREATE INDEX sample_requests_deadline ON sample_requests(effective_due_at,id);
CREATE TABLE sample_allocations (asset_id TEXT PRIMARY KEY REFERENCES sample_assets(id), request_id TEXT NOT NULL UNIQUE REFERENCES sample_requests(id), allocated_at TEXT NOT NULL, operation_id TEXT NOT NULL);
CREATE TABLE sample_decisions (request_id TEXT PRIMARY KEY REFERENCES sample_requests(id), kind TEXT NOT NULL CHECK(kind IN ('approve','reject')), actor_id TEXT NOT NULL REFERENCES users(id), reason TEXT NOT NULL, recorded_at TEXT NOT NULL, operation_id TEXT NOT NULL UNIQUE);
CREATE TABLE sample_agreement_versions (request_id TEXT NOT NULL REFERENCES sample_requests(id), revision_no INTEGER NOT NULL, terms_version TEXT NOT NULL REFERENCES sample_terms_versions(version), snapshot_cipher TEXT NOT NULL, reason TEXT NOT NULL, kind TEXT NOT NULL, created_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL, pdf_status TEXT NOT NULL DEFAULT 'queued', document_id TEXT, font_manifest_hash TEXT, PRIMARY KEY(request_id,revision_no));
CREATE TABLE sample_document_objects (document_id TEXT PRIMARY KEY, request_id TEXT NOT NULL, revision_no INTEGER NOT NULL, attempt_id TEXT NOT NULL UNIQUE, object_key TEXT NOT NULL UNIQUE, sha256 TEXT NOT NULL, size INTEGER NOT NULL, page_count INTEGER NOT NULL, created_at TEXT NOT NULL, FOREIGN KEY(request_id,revision_no) REFERENCES sample_agreement_versions(request_id,revision_no));
CREATE TABLE sample_files (id TEXT PRIMARY KEY, request_id TEXT NOT NULL REFERENCES sample_requests(id), original_key TEXT NOT NULL UNIQUE, upload_id TEXT, parts_json TEXT NOT NULL DEFAULT '[]', name TEXT NOT NULL, mime TEXT NOT NULL, original_size INTEGER, original_hash TEXT, derivative_key TEXT, derivative_size INTEGER, derivative_hash TEXT, status TEXT NOT NULL DEFAULT 'uploading', created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE sample_version_files (request_id TEXT NOT NULL, revision_no INTEGER NOT NULL, file_id TEXT NOT NULL REFERENCES sample_files(id), position INTEGER NOT NULL, note TEXT NOT NULL DEFAULT '', PRIMARY KEY(request_id,revision_no,file_id), FOREIGN KEY(request_id,revision_no) REFERENCES sample_agreement_versions(request_id,revision_no));
CREATE TABLE sample_progress (request_id TEXT PRIMARY KEY REFERENCES sample_requests(id), shipped_at TEXT, returned_at TEXT, inspected_at TEXT, inspection_note TEXT, refund_due_at TEXT, refund_calendar_revision TEXT, billing_basis_revision INTEGER, updated_at TEXT NOT NULL);
CREATE TABLE sample_quotes (id TEXT PRIMARY KEY, request_id TEXT NOT NULL REFERENCES sample_requests(id), quote_revision INTEGER NOT NULL, quote_json TEXT NOT NULL, recorded_at TEXT NOT NULL, operation_id TEXT NOT NULL, UNIQUE(request_id,quote_revision));
CREATE TABLE sample_financial_entries (id TEXT PRIMARY KEY, request_id TEXT NOT NULL REFERENCES sample_requests(id), kind TEXT NOT NULL, currency TEXT NOT NULL CHECK(currency IN ('CNY','USD')), amount_minor INTEGER NOT NULL CHECK(amount_minor>=0), occurred_at TEXT NOT NULL, recorded_at TEXT NOT NULL, actor_id TEXT NOT NULL REFERENCES users(id), reference TEXT, quote_id TEXT REFERENCES sample_quotes(id), assessment_id TEXT, details_json TEXT NOT NULL, reverses_entry_id TEXT UNIQUE REFERENCES sample_financial_entries(id), voided_by TEXT REFERENCES sample_financial_entries(id), operation_id TEXT NOT NULL UNIQUE);
CREATE UNIQUE INDEX sample_cash_reference ON sample_financial_entries(request_id,kind,reference) WHERE reference IS NOT NULL AND voided_by IS NULL AND kind IN ('receipt','refund');
CREATE TABLE sample_assessments (id TEXT PRIMARY KEY, request_id TEXT NOT NULL REFERENCES sample_requests(id), currency TEXT NOT NULL CHECK(currency IN ('CNY','USD')), amount_minor INTEGER NOT NULL CHECK(amount_minor>=0), basis_revision INTEGER NOT NULL, reason TEXT NOT NULL, completed INTEGER NOT NULL CHECK(completed IN (0,1)), created_at TEXT NOT NULL, actor_id TEXT NOT NULL REFERENCES users(id), operation_id TEXT NOT NULL UNIQUE);
CREATE TABLE sample_financial_projections (request_id TEXT PRIMARY KEY REFERENCES sample_requests(id), projection_json TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE sample_losses (request_id TEXT PRIMARY KEY REFERENCES sample_requests(id), asset_id TEXT NOT NULL REFERENCES sample_assets(id), verified_at TEXT NOT NULL, reason TEXT NOT NULL, evidence TEXT NOT NULL, conversion_at TEXT, notification_evidence TEXT, compensation_due_at TEXT, closed_at TEXT, recovered_at TEXT);
CREATE TABLE sample_extensions (id TEXT PRIMARY KEY, request_id TEXT NOT NULL REFERENCES sample_requests(id), received_at TEXT NOT NULL, requested_due_at TEXT NOT NULL, decision TEXT NOT NULL, reason TEXT NOT NULL, previous_due_at TEXT NOT NULL, recorded_at TEXT NOT NULL, actor_id TEXT NOT NULL REFERENCES users(id), operation_id TEXT NOT NULL UNIQUE);
CREATE TABLE sample_events (id TEXT PRIMARY KEY, request_id TEXT REFERENCES sample_requests(id), asset_id TEXT REFERENCES sample_assets(id), actor_id TEXT, action TEXT NOT NULL, details_json TEXT NOT NULL, occurred_at TEXT NOT NULL, recorded_at TEXT NOT NULL, corrects_event_id TEXT UNIQUE REFERENCES sample_events(id), operation_id TEXT NOT NULL UNIQUE);
CREATE INDEX sample_events_request ON sample_events(request_id,recorded_at,id);
CREATE TABLE sample_operations (id TEXT PRIMARY KEY, kind TEXT NOT NULL, request_id TEXT, actor_id TEXT, created_at TEXT NOT NULL);
CREATE TABLE sample_counters (name TEXT PRIMARY KEY, value INTEGER NOT NULL);
INSERT INTO sample_counters VALUES ('request',0);
CREATE TABLE sample_idempotency (scope TEXT NOT NULL, key TEXT NOT NULL, payload_hash TEXT NOT NULL, result_json TEXT NOT NULL, recorded_at TEXT NOT NULL, PRIMARY KEY(scope,key));
CREATE TABLE sample_jobs (id TEXT PRIMARY KEY, request_id TEXT NOT NULL, revision_no INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'queued', next_attempt_at TEXT NOT NULL, attempt_count INTEGER NOT NULL DEFAULT 0, lease_owner TEXT, lease_expires_at TEXT, lease_generation INTEGER NOT NULL DEFAULT 0, last_enqueued_at TEXT, error_code TEXT, error_detail TEXT, created_at TEXT NOT NULL, UNIQUE(request_id,revision_no), FOREIGN KEY(request_id,revision_no) REFERENCES sample_agreement_versions(request_id,revision_no));
CREATE INDEX sample_jobs_due ON sample_jobs(status,next_attempt_at,lease_expires_at);
CREATE TABLE sample_settings_versions (id TEXT PRIMARY KEY, kind TEXT NOT NULL, data_json TEXT NOT NULL, active INTEGER NOT NULL CHECK(active IN (0,1)), created_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL);
CREATE UNIQUE INDEX sample_active_settings ON sample_settings_versions(kind) WHERE active=1;
CREATE TABLE sample_security_events (id TEXT PRIMARY KEY, actor_id TEXT, action TEXT NOT NULL, ip TEXT, occurred_at TEXT NOT NULL);
CREATE INDEX sample_security_time ON sample_security_events(occurred_at);
